Here is the commit message:
drm/v3d: Prevent out of bounds access in performance query
 extensions
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Check that the number of perfmons userspace is passing in the copy and
reset extensions is not greater than the internal kernel storage where
the ids will be copied into.

Signed-off-by: Tvrtko Ursulin <tvrtko.ursulin@igalia.com>
Fixes: bae7cb5d6800 ("drm/v3d: Create a CPU job extension for the reset performance query job")
Cc: Maíra Canal <mcanal@igalia.com>
Cc: Iago Toral Quiroga <itoral@igalia.com>
Cc: stable@vger.kernel.org # v6.8+
Reviewed-by: Iago Toral Quiroga <itoral@igalia.com>
Reviewed-by: Maíra Canal <mcanal@igalia.com>
Signed-off-by: Maíra Canal <mcanal@igalia.com>
Link: https://patchwork.freedesktop.org/patch/msgid/20240711135340.84617-2-tursulin@igalia.com
(cherry picked from commit f32b5128d2c440368b5bf3a7a356823e235caabb)
Signed-off-by: Thomas Zimmermann <tzimmermann@suse.de>

Here is the root cause:
The bug was caused by a lack of validation for the number of performance monitors (`nperfmons`) provided by userspace in the performance query extensions. This allowed userspace to potentially request more performance monitors than the kernel's internal storage could accommodate, leading to out-of-bounds access and possible memory corruption.

Here is the patch:

 static int
 v3d_get_cpu_reset_performance_params(struct drm_file *file_priv,
 				     struct drm_v3d_extension __user *ext,
 				     struct v3d_cpu_job *job)
 {
 	u32 __user *syncs;
 	u64 __user *kperfmon_ids;
 	struct drm_v3d_reset_performance_query reset;

 	if (!job) {
 		DRM_DEBUG("CPU job extension was attached to a GPU job.\n");
 		return -EINVAL;
 	}

 	if (job->job_type) {
 		DRM_DEBUG("Two CPU job extensions were added to the same CPU job.\n");
 		return -EINVAL;
 	}

 	if (copy_from_user(&reset, ext, sizeof(reset)))
 		return -EFAULT;

+	if (reset.nperfmons > V3D_MAX_PERFMONS)
+		return -EINVAL;
+
 	job->job_type = V3D_CPU_JOB_TYPE_RESET_PERFORMANCE_QUERY;

 	job->performance_query.queries = kvmalloc_array(reset.count,
 							sizeof(struct v3d_performance_query),
 							GFP_KERNEL);
 	if (!job->performance_query.queries)
 		return -ENOMEM;

 	syncs = u64_to_user_ptr(reset.syncs);
 	kperfmon_ids = u64_to_user_ptr(reset.kperfmon_ids);

 	for (int i = 0; i < reset.count; i++) {
 		u32 sync;
 		u64 ids;
 		u32 __user *ids_pointer;
 		u32 id;

 		if (copy_from_user(&sync, syncs++, sizeof(sync))) {
 			kvfree(job->performance_query.queries);
 			return -EFAULT;
 		}

 		job->performance_query.queries[i].syncobj = drm_syncobj_find(file_priv, sync);

 		if (copy_from_user(&ids, kperfmon_ids++, sizeof(ids))) {
 			kvfree(job->performance_query.queries);
 			return -EFAULT;
 		}

 		ids_pointer = u64_to_user_ptr(ids);

 		for (int j = 0; j < reset.nperfmons; j++) {
 			if (copy_from_user(&id, ids_pointer++, sizeof(id))) {
 				kvfree(job->performance_query.queries);
 				return -EFAULT;
 			}

 			job->performance_query.queries[i].kperfmon_ids[j] = id;
 		}
 	}
 	job->performance_query.count = reset.count;
 	job->performance_query.nperfmons = reset.nperfmons;

 	return 0;
 }

 static int
 v3d_get_cpu_copy_performance_query_params(struct drm_file *file_priv,
 					  struct drm_v3d_extension __user *ext,
 					  struct v3d_cpu_job *job)
 {
 	u32 __user *syncs;
 	u64 __user *kperfmon_ids;
 	struct drm_v3d_copy_performance_query copy;

 	if (!job) {
 		DRM_DEBUG("CPU job extension was attached to a GPU job.\n");
 		return -EINVAL;
 	}

 	if (job->job_type) {
 		DRM_DEBUG("Two CPU job extensions were added to the same CPU job.\n");
 		return -EINVAL;
 	}

 	if (copy_from_user(&copy, ext, sizeof(copy)))
 		return -EFAULT;

 	if (copy.pad)
 		return -EINVAL;

+	if (copy.nperfmons > V3D_MAX_PERFMONS)
+		return -EINVAL;
+
 	job->job_type = V3D_CPU_JOB_TYPE_COPY_PERFORMANCE_QUERY;

 	job->performance_query.queries = kvmalloc_array(copy.count,
 							sizeof(struct v3d_performance_query),
 							GFP_KERNEL);
 	if (!job->performance_query.queries)
 		return -ENOMEM;

 	syncs = u64_to_user_ptr(copy.syncs);
 	kperfmon_ids = u64_to_user_ptr(copy.kperfmon_ids);

 	for (int i = 0; i < copy.count; i++) {
 		u32 sync;
 		u64 ids;
 		u32 __user *ids_pointer;
 		u32 id;

 		if (copy_from_user(&sync, syncs++, sizeof(sync))) {
 			kvfree(job->performance_query.queries);
 			return -EFAULT;
 		}

 		job->performance_query.queries[i].syncobj = drm_syncobj_find(file_priv, sync);

 		if (copy_from_user(&ids, kperfmon_ids++, sizeof(ids))) {
 			kvfree(job->performance_query.queries);
 			return -EFAULT;
 		}

 		ids_pointer = u64_to_user_ptr(ids);

 		for (int j = 0; j < copy.nperfmons; j++) {
 			if (copy_from_user(&id, ids_pointer++, sizeof(id))) {
 				kvfree(job->performance_query.queries);
 				return -EFAULT;
 			}

 			job->performance_query.queries[i].kperfmon_ids[j] = id;
 		}
 	}
 	job->performance_query.count = copy.count;
 	job->performance_query.nperfmons = copy.nperfmons;
 	job->performance_query.ncounters = copy.ncounters;

 	job->copy.do_64bit = copy.do_64bit;
 	job->copy.do_partial = copy.do_partial;
 	job->copy.availability_bit = copy.availability_bit;
 	job->copy.offset = copy.offset;
 	job->copy.stride = copy.stride;

 	return 0;
 }



